const REQUEST_COLLECTION_PLAN_GLOBAL_DEADLINE_MS = 12_800;
const REQUEST_COLLECTION_PLAN_AI_RESCUE_DEADLINE_MS = 13_800;
const REQUEST_COLLECTION_PLAN_AI_FINAL_RESCUE_DEADLINE_MS = 16_000;
